// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address caller, uint256 ts) public {
        vm.assume(caller != address(0));

        uint256 targetTs = bound(ts, block.timestamp + 1, block.timestamp + 1 days);

        vm.deal(caller, 100 ether);

        vm.warp(targetTs);

        vm.prank(caller);
        (bool ok, ) = address(c).call{value: 10 ether}("\x00");

        if (!ok) return;

        assertTrue(c.pastBlockTime() != targetTs);
    }
}
